[
    {"title":"应收账款账龄结构","value":"2017年12月31日，1年以内账款占比71.24%，1-2年占比18.68%。","evidence":"2017年12月31日账龄表中，1年以内金额3,349.60，比例71.24%；1-2年金额878.37，比例18.68%。","type":"table_fact"},
    {"title":"应收账款余额趋势","value":"2016年末至2019年6月末，应收账款余额从5,735.36万元下降至2,820.51万元。","evidence":"2016/12/31余额5,735.36万元，2019/6/30余额2,820.51万元。","type":"table_fact"},
    {"title":"期后回款趋势","value":"2016年末至2019年6月末，期后回款金额从5,257.70万元下降至1,758.46万元。","evidence":"2016/12/31期后回款5,257.70万元，2019/6/30期后回款1,758.46万元。","type":"table_fact"},
    {"title":"应收账款占比下降","value":"2017年末应收账款余额占整体比例为17.88%，较2016年末的34.64%下降。","evidence":"2017年末余额4,701.62万元，占整体比例17.88%；2016年末余额5,735.36万元，占整体比例34.64%。","type":"table_fact"}
]

